describeMatrix("serve static range requests", (t, { it, expect }) => {
  const CONTENT = "abcdefghij".repeat(100);
  const meta = {
    type: "text/plain",
    etag: '"abc"',
    mtime: 1_700_000_000_000,
    size: 1000,
  };

  beforeEach(() => {
    t.app.all("/range/**", (event) =>
      serveStatic(event, {
        getMeta: (id) => (id.includes("404") ? undefined : meta),
        getContents: () => CONTENT,
      }),
    );
  });

  it("advertises accept-ranges on GET and HEAD 200", async () => {
    const res = await t.fetch("/range/file.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-length")).toBe("1000");

    const headRes = await t.fetch("/range/file.txt", { method: "HEAD" });
    expect(headRes.status).toBe(200);
    expect(headRes.headers.get("accept-ranges")).toBe("bytes");
    expect(headRes.headers.get("content-length")).toBe("1000");
  });

  it("does not advertise accept-ranges without a known size", async () => {
    t.app.all("/nosize/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ type: "text/plain" }),
        getContents: () => CONTENT,
      }),
    );
    const res = await t.fetch("/nosize/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBeNull();
    expect(await res.text()).toBe(CONTENT);
  });

  it("does not advertise accept-ranges on a 304", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { "if-none-match": '"abc"' } });
    expect(res.status).toBe(304);
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("answers 304 before evaluating Range", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { "if-none-match": '"abc"', range: "bytes=0-9" },
    });
    expect(res.status).toBe(304);
    expect(await res.text()).toBe("");
  });

  it("responds 206 with the exact byte range and validators of the 200", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=100-199" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 100-199/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe(CONTENT.slice(100, 200));

    const fullRes = await t.fetch("/range/file.txt");
    expect(res.headers.get("etag")).toBe(fullRes.headers.get("etag"));
    expect(res.headers.get("last-modified")).toBe(fullRes.headers.get("last-modified"));
  });

  it("uses the range length even when options.headers sets content-length", async () => {
    t.app.all("/clen-range/**", (event) =>
      serveStatic(event, {
        getMeta: () => meta,
        getContents: () => CONTENT,
        headers: { "content-length": "999" },
      }),
    );
    const res = await t.fetch("/clen-range/file.txt", { headers: { range: "bytes=100-199" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("100");
  });

  it("clamps open and suffix ranges to the asset size", async () => {
    let res = await t.fetch("/range/file.txt", { headers: { range: "bytes=900-5000" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 900-999/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe(CONTENT.slice(900));

    res = await t.fetch("/range/file.txt", { headers: { range: "bytes=-5000" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-999/1000");
    expect(res.headers.get("content-length")).toBe("1000");
    expect(await res.text()).toBe(CONTENT);

    res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99999999999999999999999" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-999/1000");
  });

  it("responds 416 for unsatisfiable ranges", async () => {
    for (const range of ["bytes=1000-", "bytes=-0"]) {
      const res = await t.fetch("/range/file.txt", { headers: { range } });
      expect(res.status, range).toBe(416);
      expect(res.headers.get("content-range"), range).toBe("bytes */1000");
      expect(res.headers.get("content-length"), range).toBe("0");
      expect(res.headers.get("accept-ranges"), range).toBe("bytes");
      expect(await res.text(), range).toBe("");
    }

    t.app.all("/empty/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ ...meta, size: 0 }),
        getContents: () => "",
      }),
    );
    const res = await t.fetch("/empty/file.txt", { headers: { range: "bytes=0-0" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */0");
    expect(res.headers.get("content-length")).toBe("0");
  });

  it("ignores malformed, multiple or reversed ranges", async () => {
    for (const range of ["bytes=0-1,5-9", "items=0-5", "bytes=500-100", "bytes=abc"]) {
      const res = await t.fetch("/range/file.txt", { headers: { range } });
      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-length"), range).toBe("1000");
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(res.headers.get("accept-ranges"), range).toBe("bytes");
      expect(await res.text(), range).toBe(CONTENT);
    }
  });

  it("answers HEAD with 206 headers without calling getContents", async () => {
    const getContents = vi.fn(() => CONTENT);
    t.app.all("/head/**", (event) => serveStatic(event, { getMeta: () => meta, getContents }));

    const res = await t.fetch("/head/file.txt", {
      method: "HEAD",
      headers: { range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("honors If-Range only when the ETag matches", async () => {
    let res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-9", "if-range": '"xyz"' },
    });
    expect(res.status).toBe(200);
