  });
});

describeMatrix("serve static range requests", (t, { it, expect }) => {
  const CONTENT = "abcdefghij".repeat(100);
  const meta = {
    type: "text/plain",
    etag: '"abc"',
    mtime: 1_700_000_000_000,
    size: 1000,
  };

  beforeEach(() => {
    t.app.all("/range/**", (event) =>
      serveStatic(event, {
        getMeta: (id) => (id.includes("404") ? undefined : meta),
        getContents: () => CONTENT,
      }),
    );
  });

  it("advertises accept-ranges on GET and HEAD 200", async () => {
    const res = await t.fetch("/range/file.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-length")).toBe("1000");

    const headRes = await t.fetch("/range/file.txt", { method: "HEAD" });
    expect(headRes.status).toBe(200);
    expect(headRes.headers.get("accept-ranges")).toBe("bytes");
    expect(headRes.headers.get("content-length")).toBe("1000");
  });

  it("does not advertise accept-ranges without a known size", async () => {
    t.app.all("/nosize/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ type: "text/plain" }),
        getContents: () => CONTENT,
      }),
    );
    const res = await t.fetch("/nosize/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBeNull();
    expect(await res.text()).toBe(CONTENT);
  });

  it("does not advertise accept-ranges on a 304", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { "if-none-match": '"abc"' } });
    expect(res.status).toBe(304);
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("answers 304 before evaluating Range", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { "if-none-match": '"abc"', range: "bytes=0-9" },
    });
    expect(res.status).toBe(304);
    expect(await res.text()).toBe("");
  });

  it("responds 206 with the exact byte range and validators of the 200", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=100-199" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 100-199/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe(CONTENT.slice(100, 200));

    const fullRes = await t.fetch("/range/file.txt");
    expect(res.headers.get("etag")).toBe(fullRes.headers.get("etag"));
    expect(res.headers.get("last-modified")).toBe(fullRes.headers.get("last-modified"));
  });

  it("uses the range length even when options.headers sets content-length", async () => {
    t.app.all("/clen-range/**", (event) =>
      serveStatic(event, {
        getMeta: () => meta,
        getContents: () => CONTENT,
        headers: { "content-length": "999" },
      }),
    );
    const res = await t.fetch("/clen-range/file.txt", { headers: { range: "bytes=100-199" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("100");
  });

  it("clamps open and suffix ranges to the asset size", async () => {
    let res = await t.fetch("/range/file.txt", { headers: { range: "bytes=900-5000" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 900-999/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe(CONTENT.slice(900));

    res = await t.fetch("/range/file.txt", { headers: { range: "bytes=-5000" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-999/1000");
    expect(res.headers.get("content-length")).toBe("1000");
    expect(await res.text()).toBe(CONTENT);

    res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99999999999999999999999" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-999/1000");
  });

  it("responds 416 for unsatisfiable ranges", async () => {
    for (const range of ["bytes=1000-", "bytes=-0"]) {
      const res = await t.fetch("/range/file.txt", { headers: { range } });
      expect(res.status, range).toBe(416);
      expect(res.headers.get("content-range"), range).toBe("bytes */1000");
      expect(res.headers.get("content-length"), range).toBe("0");
      expect(res.headers.get("accept-ranges"), range).toBe("bytes");
      expect(await res.text(), range).toBe("");
    }

    t.app.all("/empty/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ ...meta, size: 0 }),
        getContents: () => "",
      }),
    );
    const res = await t.fetch("/empty/file.txt", { headers: { range: "bytes=0-0" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */0");
    expect(res.headers.get("content-length")).toBe("0");
  });

  it("ignores malformed, multiple or reversed ranges", async () => {
    for (const range of ["bytes=0-1,5-9", "items=0-5", "bytes=500-100", "bytes=abc"]) {
      const res = await t.fetch("/range/file.txt", { headers: { range } });
      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-length"), range).toBe("1000");
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(res.headers.get("accept-ranges"), range).toBe("bytes");
      expect(await res.text(), range).toBe(CONTENT);
    }
  });

  it("answers HEAD with 206 headers without calling getContents", async () => {
    const getContents = vi.fn(() => CONTENT);
    t.app.all("/head/**", (event) => serveStatic(event, { getMeta: () => meta, getContents }));

    const res = await t.fetch("/head/file.txt", {
      method: "HEAD",
      headers: { range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("honors If-Range only when the ETag matches", async () => {
    let res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-9", "if-range": '"xyz"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(CONTENT);

    res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-9", "if-range": '"abc"' },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("10");
  });

  it("never matches a weak ETag in If-Range", async () => {
    t.app.all("/weak/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ ...meta, etag: 'W/"abc"' }),
        getContents: () => CONTENT,
      }),
    );
    for (const ifRange of ['W/"abc"', '"abc"']) {
      const res = await t.fetch("/weak/file.txt", {
        headers: { range: "bytes=0-9", "if-range": ifRange },
      });
      expect(res.status, ifRange).toBe(200);
    }
  });

  it("compares If-Range dates with the asset mtime", async () => {
    const exact = new Date(1_700_000_000_000).toUTCString();
    const oneSecondBefore = new Date(1_700_000_000_000 - 1000).toUTCString();

    let res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-9", "if-range": exact },
    });
    expect(res.status).toBe(206);

    res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-9", "if-range": oneSecondBefore },
    });
    expect(res.status).toBe(200);

    t.app.all("/nomtime/**", (event) =>
      serveStatic(event, { getMeta: () => ({ size: 1000 }), getContents: () => CONTENT }),
    );
    res = await t.fetch("/nomtime/file.txt", {
      headers: { range: "bytes=0-9", "if-range": exact },
    });
    expect(res.status).toBe(200);
  });

  it("applies the range to the precompressed variant", async () => {
    t.app.all("/gz/**", (event) =>
      serveStatic(event, {
        getMeta: (id) =>
          id === "/gz/app.js.gz" ? { type: "text/javascript", encoding: "gzip", size: 300 } : undefined,
        getContents: (id) => (id === "/gz/app.js.gz" ? "g".repeat(300) : undefined),
        encodings: { gzip: ".gz" },
      }),
    );
    const res = await t.fetch("/gz/app.js", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/300");
    expect(res.headers.get("content-length")).toBe("100");
    expect(res.headers.get("content-encoding")).toBe("gzip");
    // The body is a raw fragment, not a valid gzip stream: skip decoding it.
    await res.body?.cancel();
  });

  it("reads a stream only up to the last byte of the range", async () => {
    let pulls = 0;
    let cancelled = false;
    t.app.all("/stream/**", (event) =>
      serveStatic(event, {
        getMeta: () => meta,
        getContents: () =>
          new ReadableStream<Uint8Array>(
            {
              pull(controller) {
                pulls++;
                if (pulls > 1000) {
                  controller.close();
                  return;
                }
                controller.enqueue(new Uint8Array([97 + ((pulls - 1) % 26)]));
              },
              cancel() {
                cancelled = true;
              },
            },
            { highWaterMark: 0 },
          ),
      }),
    );

    const res = await t.fetch("/stream/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe(CONTENT.slice(0, 10));
    expect(pulls).toBe(10);
    expect(cancelled).toBe(true);
  });

  it("returns the same range body for every getContents type", async () => {
    const bodies: Record<string, () => BodyInit> = {
      string: () => CONTENT,
      Uint8Array: () => new TextEncoder().encode(CONTENT),
      ArrayBuffer: () => new TextEncoder().encode(CONTENT).buffer as ArrayBuffer,
      Blob: () => new Blob([CONTENT]),
      ReadableStream: () => new Response(CONTENT).body!,
    };
    for (const [name, getContents] of Object.entries(bodies)) {
      t.app.all(`/types/${name}/**`, (event) =>
        serveStatic(event, { getMeta: () => meta, getContents }),
      );
      const res = await t.fetch(`/types/${name}/file.txt`, {
        headers: { range: "bytes=100-199" },
      });
      expect(res.status, name).toBe(206);
      expect(await res.text(), name).toBe(CONTENT.slice(100, 200));
    }
  });

  it("keeps 404 and 405 unchanged when Range is sent", async () => {
    const notFound = await t.fetch("/range/404.txt", { headers: { range: "bytes=0-9" } });
    expect(notFound.status).toBe(404);

    const post = await t.fetch("/range/file.txt", {
      method: "POST",
      headers: { range: "bytes=0-9" },
    });
    expect(post.status).toBe(405);
    expect(post.headers.get("allow")).toBe("GET, HEAD");
  });
});

describe("serve static (malformed url)", () => {
  it("falls through on a malformed `%` instead of throwing", async () => {
    // With `allowMalformedURL`, a raw malformed `%` (e.g. `/foo%`) reaches
    // serveStatic and the final `decodeURI` would throw a URIError — a 500 that
    // bypasses `fallthrough`. The guarded decode falls back to the resolved id
    // so `fallthrough` (and 404 when off) are reached as normal.
    const options: ServeStaticOptions = {
      getContents: () => undefined,
      getMeta: () => undefined,
    };

    const fallthroughApp = new H3({ allowMalformedURL: true })
      .use((event) => serveStatic(event, { ...options, fallthrough: true }))
      .use(() => "next");
    const res = await fallthroughApp.request("/foo%");
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("next");

    const notFoundApp = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, options),
    );
    const res404 = await notFoundApp.request("/foo%");
    expect(res404.status).toBe(404);
  });

  it("never hands a raw backslash or bare `..` to the backend under allowMalformedURL", async () => {
    // Defense-in-depth guard for the trickiest input we could construct: a
    // malformed `%` (forcing the raw pathname) whose segment is popped by a
    // `..`, leaving single-encoded `%5c` separators. If the on-disk decode
    // (`%5c` → `\`) were not neutralized, the id would become
    // `/..\..\windows\win.ini` — a traversal above the root on backslash-aware
    // (e.g. Windows) filesystem backends. It is neutralized because serveStatic
    // re-resolves dot segments *after* that decode. The event layer cannot help
    // here: canonicalization never decodes a separator (and is skipped entirely
    // for a malformed path), so `%5c` reaches serveStatic in its wire form.
    let servedId: string | undefined;
    const app = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, {
        getContents: (id) => {
          servedId = id;
          return `asset:${id}`;
        },
        getMeta: () => ({ size: 1 }),
      }),
    );

    const res = await app.request("/a%ZZ/../..%5c..%5cwindows%5cwin.ini");
    expect(res.status).toBe(200);
    expect(servedId).toBeDefined();
    expect(servedId).not.toContain("\\"); // no raw backslash separator
    expect(servedId).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/); // no bare `..` segment
  });
});

